using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {static class ComponentEvidence {
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=4194304};}
 public static string Compare(string local,string remote){return string.IsNullOrEmpty(remote)?"unknown":string.IsNullOrEmpty(local)?"missing":local==remote?"latest":"available";}
 public static ulong[] Items(string key){if(key=="buddy")return new[]{CoreComponents.Buddy};if(key=="viewpoint")return new[]{CoreComponents.Viewpoint};if(key=="base")return InstallWorkflow.Requested(false);if(key=="models")return new[]{3810302175UL};if(key=="shoot")return new[]{ShootClient.Item};if(key=="chinese")return new[]{ChinesePatch.Item};return new[]{ViewpointAddons.Get(key).Item};}
 public static string Manifest(Engine e,ulong item){string path=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(e.Workshop)),"appworkshop_108600.acf");try{LauncherMaintenance.NoReparse(path);if(!File.Exists(path)||new FileInfo(path).Length>4194304)return "";string text=File.ReadAllText(path);var section=Regex.Match(text,@"\""WorkshopItemsInstalled\""\s*\{(?<body>.*?)\}\s*\""WorkshopItemDetails",RegexOptions.Singleline);string body=section.Success?section.Groups["body"].Value:text;var match=Regex.Match(body,@"\"""+item+@"\""\s*\{[^}]*\""manifest\""\s*\""(\d+)\""");return match.Success?match.Groups[1].Value:"";}catch{return "";}}
 static IEnumerable<string> SafeFiles(string root){LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))yield break;foreach(string file in Directory.GetFiles(root)){string ext=Path.GetExtension(file);if(Path.GetFileName(file)=="mod.info"||ext==".jar"||ext==".dll"||ext==".lua"){LauncherMaintenance.NoReparse(file);yield return file;}}foreach(string dir in Directory.GetDirectories(root)){LauncherMaintenance.NoReparse(dir);foreach(string file in SafeFiles(dir))yield return file;}}
 static IEnumerable<string> CodeFiles(string source){string mods=Path.Combine(source,"mods");LauncherMaintenance.NoReparse(mods);if(!Directory.Exists(mods))yield break;foreach(string folder in Directory.GetDirectories(mods)){LauncherMaintenance.NoReparse(folder);foreach(string part in new[]{folder}.Concat(Directory.GetDirectories(folder).Where(p=>Path.GetFileName(p)=="common"||Regex.IsMatch(Path.GetFileName(p),@"^4[12](?:\.\d+)*$")))){LauncherMaintenance.NoReparse(part);string info=Path.Combine(part,"mod.info");if(File.Exists(info)){LauncherMaintenance.NoReparse(info);yield return info;}foreach(string relative in new[]{"media/lua","media/java","libs"}){string root=Path.Combine(part,relative);foreach(string file in SafeFiles(root))yield return file;}}}}
 public static string Fingerprint(Engine e,string key){var files=new List<string>();foreach(ulong id in Items(key)){string source=InstallWorkflow.Source(e,id);if(!Directory.Exists(source))return "";files.AddRange(CodeFiles(source));}if(files.Count>10000)throw new Exception("扩展代码文件数量超过限制。");return DlssInstaller.Hash(Encoding.UTF8.GetBytes(string.Join("|",files.OrderBy(x=>x).Select(p=>p+"="+DlssInstaller.HashFile(p)))+string.Join("|",Items(key).Select(i=>Manifest(e,i)))));}
 static string Receipt(Engine e,string key){Items(key);return Path.Combine(e.Data,"component-receipts",key+".json");}
 public static void Record(Engine e,string key){string hash=Fingerprint(e,key),file=Receipt(e,key);LauncherMaintenance.NoReparse(file);Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+".new-"+Guid.NewGuid().ToString("N");try{File.WriteAllText(temp,Json().Serialize(new{hash=hash,appliedUtc=DateTime.UtcNow.ToString("o")}),new UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static Dictionary<string,object> Decorate(Engine e,string key,object card){string input=Json().Serialize(card);string output=DisplayCache.Read(e,"component:"+key+":"+input,()=>Json().Serialize(DecorateFresh(e,key,card)));return Json().Deserialize<Dictionary<string,object>>(output);}
 static Dictionary<string,object> DecorateFresh(Engine e,string key,object card){var data=Json().Deserialize<Dictionary<string,object>>(Json().Serialize(card));try{string hash=Fingerprint(e,key),file=Receipt(e,key);LauncherMaintenance.NoReparse(file);string applied="",date="";if(File.Exists(file)){if(new FileInfo(file).Length>8192)throw new Exception();var receipt=Json().Deserialize<Dictionary<string,string>>(File.ReadAllText(file));applied=receipt["hash"];date=receipt["appliedUtc"];}if((key=="buddy"||key=="viewpoint")&&applied==""){string legacy=Receipt(e,"base");LauncherMaintenance.NoReparse(legacy);if(File.Exists(legacy)&&new FileInfo(legacy).Length<=8192){var old=Json().Deserialize<Dictionary<string,string>>(File.ReadAllText(legacy));string stamp;if(old.TryGetValue("appliedUtc",out stamp)){data["legacyAppliedUtc"]=stamp;data["legacyEvidenceWarning"]="此前为合并组件记录；独立组件尚未重新核对。";}}}bool configured=(bool)data["configured"];data["sourceFingerprint"]=hash;data["sourceState"]=hash==""?"missing":applied==""?"unrecorded":hash==applied?"same":"changed";data["appliedUtc"]=date;data["runtimeState"]=configured?"下次启动启用":"当前本地清单未启用";data["manifests"]=Items(key).Select(i=>new{item=i.ToString(),local=Manifest(e,i)}).ToArray();if(key=="base"||key=="buddy"){bool drift=false;foreach(string name in new[]{"ZombieBuddy.jar","zbNative.dll"}){string source=Path.Combine(e.BuddyLib,name),deployed=Path.Combine(e.Game,name);if(File.Exists(source)&&(!File.Exists(deployed)||DlssInstaller.HashFile(source)!=DlssInstaller.HashFile(deployed)))drift=true;}data["needsReapply"]=configured&&(drift||applied!=""&&hash!=applied);}else data["needsReapply"]=configured&&applied!=""&&hash!=applied;}catch(Exception ex){data["sourceState"]="unknown";data["evidenceWarning"]="无法完整核对来源："+ex.Message;}
  if(key=="shoot"){bool needed=new PresentationBridge().RetirementNeeded(e);data["bridgeRetirementNeeded"]=needed;if(needed){data["needsReapply"]=true;data["bridgeRetirementMessage"]="检测到已退役的启动器瞄准桥接；明确重新应用枪械组件时清理，保留作者控制与校准。";}}
  return data;}
 internal static void ReadPublishedDetails(string text,ulong[] ids,Dictionary<ulong,string> manifests,Dictionary<ulong,string> previews){
  var raw=Json().Deserialize<Dictionary<string,object>>(text);var response=(Dictionary<string,object>)raw["response"];
  foreach(Dictionary<string,object> item in (System.Collections.IEnumerable)response["publishedfiledetails"]){
   ulong id;object value;if(!item.TryGetValue("publishedfileid",out value)||!ulong.TryParse(Convert.ToString(value),out id)||!ids.Contains(id)||!item.TryGetValue("result",out value)||Convert.ToString(value)!="1"||!item.TryGetValue("consumer_app_id",out value)||Convert.ToString(value)!="108600")continue;
   if(item.TryGetValue("hcontent_file",out value)&&Regex.IsMatch(Convert.ToString(value),@"^[1-9][0-9]*$"))manifests[id]=Convert.ToString(value);
   if(item.TryGetValue("preview_url",out value)&&ModernHostPolicy.IsWorkshopImage(Convert.ToString(value)))previews[id]=Convert.ToString(value);
  }
 }
 public static object CheckUpdates(Engine e,CancellationToken token){ulong[] ids=Items("base").Concat(new[]{3810302175UL,ShootClient.Item,ChinesePatch.Item}).Concat(ViewpointAddons.All.Select(a=>a.Item)).Distinct().ToArray();var rows=new List<object>();var remote=new Dictionary<ulong,string>();var previews=new Dictionary<ulong,string>();string error="";try{var req=(HttpWebRequest)WebRequest.Create("https://api.steampowered.com/ISteamRemoteStorage/GetPublishedFileDetails/v1/");req.Method="POST";req.ContentType="application/x-www-form-urlencoded";req.Timeout=15000;req.ReadWriteTimeout=15000;byte[] body=Encoding.ASCII.GetBytes("itemcount="+ids.Length+string.Concat(ids.Select((id,n)=>"&publishedfileids%5B"+n+"%5D="+id)));using(token.Register(()=>req.Abort())){token.ThrowIfCancellationRequested();using(var stream=req.GetRequestStream())stream.Write(body,0,body.Length);using(var response=req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){char[] buffer=new char[4096];var text=new StringBuilder();int read;while((read=reader.Read(buffer,0,buffer.Length))>0){text.Append(buffer,0,read);if(text.Length>4194304)throw new Exception("工坊响应过大。");}ReadPublishedDetails(text.ToString(),ids,remote,previews);}}}catch(Exception ex){if(token.IsCancellationRequested)throw new OperationCanceledException();error="工坊版本查询失败，不能判定最新："+ex.Message;}foreach(ulong id in ids){string value;remote.TryGetValue(id,out value);string local=Manifest(e,id);rows.Add(new{item=id.ToString(),local=local,remote=value??"",state=Compare(local,value),previewUrl=previews.ContainsKey(id)?previews[id]:"",error=remote.ContainsKey(id)?"":error==""?"条目元数据暂不可用。":error});}return new{checkedUtc=DateTime.UtcNow.ToString("o"),items=rows.ToArray(),message="更新检查完成，结果已显示在组件卡片。"};}
 }}
